import {KEY,SESSION,SEATS,SLOTS,time,today,plusDay,validSlot,initial,validate,active,book,cancel,login} from "./assets/engine.js";
const $=(id)=>document.getElementById(id),icon=(id)=>`<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${id}"></use></svg>`,esc=(s)=>String(s).replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const dateLabel=(day)=>new Intl.DateTimeFormat("en",{weekday:"short",day:"numeric",month:"short",timeZone:"UTC"}).format(new Date(`${day}T12:00:00Z`));
let state=initial(),session=null,day=today(),slot=6,selected=null,busy=false,error="",notice="",ram=false,broken=false,pendingTarget=null,pendingAction=null,toastTimer,epoch=0;
const now=()=>new Date();
if(!validSlot(day,slot)){const next=SLOTS.find((s)=>validSlot(day,s.id));slot=next?.id??6;if(!next)day=plusDay(day,1);}
function readSession(){const raw=localStorage.getItem(SESSION);if(!raw)return null;const item=JSON.parse(raw);if(item.version!==1||item.id!=="EMP-DEMO"||item.name!=="Alex Sample")throw Error("Invalid sample session. Sign in again.");return item;}
function restore(){try{if(!navigator.locks){ram=true;notice="This browser has no Web Locks. Explicit RAM-only mode: no persistence or cross-tab coordination.";}else{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):initial();session=readSession();}}catch(e){broken=true;notice=`${e.message} Stored content is preserved. Use Reset demo to start clean, or view the floor without writing.`;}}
restore();
function toast(text){$("toast").textContent=text;$("toast").hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").hidden=true,3500);}
function announce(message){error=message;render();}
async function mutate(fn){
  const apply=()=>{if(broken)throw Error("Saved data is protected. Reset this demo explicitly before writing.");const fresh=ram?structuredClone(state):validate(JSON.parse(localStorage.getItem(KEY)||JSON.stringify(initial())));const result=fn(fresh);validate(fresh);if(!ram)localStorage.setItem(KEY,JSON.stringify(fresh));state=fresh;return result;};
  return ram?apply():navigator.locks.request(KEY,apply);
}
function account(){
  $("account").innerHTML=session?`<div class="account"><span class="avatar">AS</span><span>Alex Sample<small>Public demo employee</small></span><button class="icon-button" id="logout" aria-label="Sign out of demo">${icon("logout")}</button></div>`:`<div class="account"><button class="primary" id="open-login">Try demo login ${icon("login")}</button></div>`;
  const hash=location.hash||"#floor";$("nav-floor").classList.toggle("active",hash==="#floor");$("nav-bookings").classList.toggle("active",hash==="#bookings");
  $("storage-notice").hidden=!notice;$("storage-notice").textContent=notice;
}
function selectedSlot(){return `${time(SLOTS[slot].start)} – ${time(SLOTS[slot].end)}`;}
function floor(){
  const rows=active(state,day,slot),free=30-rows.length;
  return `<div class="workspace"><aside class="panel time-column" aria-label="Date and time"><div class="day-control"><label>Plan your break<input id="day" type="date" value="${day}" min="${today()}" max="${plusDay(today(),7)}"></label><div class="clock-label">${icon("clock")}<span id="office-clock">${new Intl.DateTimeFormat("en-GB",{hour:"2-digit",minute:"2-digit",timeZone:"UTC"}).format(now())} UTC now</span></div></div><p class="slot-label">30-MINUTE SLOTS · UTC</p><div class="slots">${SLOTS.map((s)=>`<button class="slot ${slot===s.id?"selected":""}" data-slot="${s.id}" aria-pressed="${slot===s.id}" ${validSlot(day,s.id)?"":"disabled"}><span>${time(s.start)}<span class="slot-end"> – ${time(s.end)}</span></span>${slot===s.id?`<small>chosen</small>`:""}</button>`).join("")}</div></aside>
  <section class="panel floor-column" aria-label="Cafeteria floor plan"><div class="plan-heading"><div><h2>Find your spot.</h2><span class="location-label">${dateLabel(day)} · ${selectedSlot()} UTC</span></div><span class="location-label">${icon("pin")} EAST WING / 02</span></div><div class="floor"><div class="windows"></div><span class="floor-direction">NORTH-FACING WINDOWS</span><div class="table-grid">${Array.from({length:6},(_,t)=>`<div class="table-unit"><div class="table-surface"><strong>TABLE ${String(t+1).padStart(2,"0")}</strong><small>5 seats</small></div>${Array.from({length:5},(_,s)=>{const id=`T${t+1}-S${s+1}`,b=rows.find((b)=>b.seat===id),mine=Boolean(b&&session&&b.user===session.id);return `<button class="seat s${s+1} ${b?"booked":""} ${mine?"mine":""} ${selected===id?"chosen":""}" data-seat="${id}" aria-label="Table ${t+1}, seat ${s+1}: ${b?(mine?"your booking":"booked"):selected===id?"selected":"available"}" aria-pressed="${selected===id}" ${b||!validSlot(day,slot)?"disabled":""}><span>${s+1}</span></button>`;}).join("")}</div>`).join("")}</div><span class="floor-direction bottom">PANTRY & EXIT ${icon("right")}</span></div><div class="legend"><span><i class="swatch"></i>Available</span><span><i class="swatch booked"></i>Booked</span><span><i class="swatch selected"></i>Selected</span><span><i class="swatch mine"></i>Yours</span></div><div class="plan-bottom"><span><strong class="available-count">${free} seats free</strong> / 30 physical seats</span><span>Policy capacity <strong>${rows.length} / ${state.capacity}</strong></span></div></section>
  <aside class="selection-column"><section class="panel"><div class="panel-heading"><h2>Your next little break.</h2><p>A seat, not a whole table.</p></div><div class="booking-summary"><div class="seat-illustration">${icon("seat")}<span class="seat-pill">30 min, just for you</span></div><div class="receipt-row"><span>Date</span><strong>${dateLabel(day)}</strong></div><div class="receipt-row"><span>Time</span><strong>${selectedSlot()}</strong></div><div class="receipt-row"><span>Location</span><strong>Level 02 · East wing</strong></div><div class="receipt-row big"><span>Your seat</span><strong>${selected?selected.replace("-"," · "):"Choose on the plan"}</strong></div><div id="booking-error" role="alert" class="error" ${error?"":"hidden"}>${esc(error)}</div><button id="book" class="primary ${busy?"loading":""}" ${!selected||busy||broken?"disabled":""}>${busy?"Confirming…":session?"Confirm my seat":"Sign in to book"} ${icon(busy?"clock":"right")}</button><p>${session?"Local demo only. Never an actual office booking.":"Browse freely. Sign in with the public demo to book."}</p></div></section><div class="guide-mini">${icon("leaf")}<div><h3>A little room for everyone.</h3><p>One seat per person, per slot. Sharing a table starts with sharing a little space.</p></div></div></aside></div>
  <div class="bottom-bar"><div><h3>Your plans, all in one place.</h3><p>See your ${day===today()?"today's":"selected day's"} seats and make room when plans change.</p></div><a class="text-button" href="#bookings">View my bookings ${icon("arrow-up-right")}</a></div>
  <details class="lab"><summary>Public demo controls & local-data details</summary><div class="lab-content"><p>All bookings and session IDs are fictional local data. Web Locks serialize same-origin writes across tabs; storage events refresh the other tab. The capacity below is an illustrative manager policy, not a real office rule.</p><label>Capacity per slot<input id="capacity" type="number" min="1" max="30" value="${state.capacity}"></label><button class="secondary" id="save-capacity">Set demo capacity</button><button class="secondary" id="hold-seat" ${!selected?"disabled":""}>Let another sample employee take this seat</button><p>Choose and confirm a seat, then immediately use the competing-employee control to exercise SEAT_UNAVAILABLE. Lower the capacity to the occupied count to exercise MANAGER_CAPACITY_EXCEEDED. Started slots are rejected as INVALID_TIME_RANGE. No network API is called.</p></div></details>`;
}
function bookings(){
  if(!session)return `<section class="panel bookings-view"><h2>Your break, your bookings.</h2><p>Use the public demo login to view Alex Sample's local seats.</p><button class="primary" id="open-login">Try public demo login ${icon("login")}</button></section>`;
  const list=state.bookings.filter((b)=>b.user===session.id&&b.day===day).sort((a,b)=>a.slot-b.slot||a.createdAt.localeCompare(b.createdAt));
  return `<section class="panel bookings-view"><div class="view-heading"><div><p class="eyebrow">${day===today()?"TODAY'S":dateLabel(day).toUpperCase()} PLANS · UTC</p><h2>Room in your day.</h2></div><a class="secondary" href="#floor">Find a seat ${icon("right")}</a></div><label>Booking date<input id="day" type="date" value="${day}" min="${today()}" max="${plusDay(today(),7)}"></label>${list.length?list.map((b)=>`<article class="booking-card"><div><strong>${b.seat.replace("-"," · ")}</strong><small>${dateLabel(b.day)} · ${time(SLOTS[b.slot].start)}–${time(SLOTS[b.slot].end)} UTC · East wing</small></div><span class="status ${b.status==="CANCELLED"?"cancelled":""}">${b.status}</span>${b.status==="BOOKED"&&validSlot(b.day,b.slot)?`<button class="secondary" data-cancel="${esc(b.id)}">Cancel seat</button>`:""}</article>`).join(""):`<div class="empty">${icon("coffee")}<h3>No plans, yet.</h3><p>No local seats reserved for ${dateLabel(day)}. Your next good break is a click away.</p></div>`}</section>`;
}
function guide(){return `<section class="panel guide-view"><p class="eyebrow">A BETTER KIND OF BREAK</p><h2>A small ritual, made simpler.</h2><div class="guide-grid"><div><span>01 / PICK YOUR MOMENT</span><h3>Thirty minutes for you.</h3><p>Choose a future slot between 09:00 and 17:00 UTC, today or up to seven days ahead. An ongoing slot is closed to new bookings.</p></div><div><span>02 / FIND YOUR SPACE</span><h3>A chair, not a table.</h3><p>Six tables, five chairs each. Green seats are physically free, red are occupied, amber is your selection and blue is your own booking.</p></div><div><span>03 / MAKE IT YOURS</span><h3>Confirm. Then recharge.</h3><p>Use the public mock login. The latest stored availability and capacity are checked atomically on confirmation. Cancel a future booking to free the seat.</p></div></div><div class="notice">This static concept adapts the frontend task list to native HTML, CSS and JavaScript. No Next.js runtime, real API endpoint, manager authentication, employee identity, or shared server exists. Browser guards are UX only.</div><a class="primary" href="#floor">Back to the common room ${icon("right")}</a></section>`;}
function render(){const labOpen=document.querySelector(".lab")?.open,focused=document.activeElement,focusSeat=focused?.dataset.seat,focusSlot=focused?.dataset.slot;account();const hash=location.hash||"#floor";$("view").innerHTML=hash==="#bookings"?bookings():hash==="#guide"?guide():hash==="#floor"?floor():`<section class="panel guide-view"><h2>This corner isn't on the plan.</h2><a class="primary" href="#floor">Back to the floor ${icon("right")}</a></section>`;if(labOpen&&document.querySelector(".lab"))document.querySelector(".lab").open=true;if(focusSeat)document.querySelector(`[data-seat="${focusSeat}"]`)?.focus({preventScroll:true});if(focusSlot)document.querySelector(`[data-slot="${focusSlot}"]`)?.focus({preventScroll:true});}
function openLogin(target=null){if(broken){toast("Reset the protected invalid demo data before signing in.");return;}pendingTarget=target;$("login-error").textContent="";$("login").showModal();}
async function createBooking(){
  if(!session){openLogin("book");return;}if(!selected||busy)return;
  const payload={day,slot,seat:selected,user:session.id},token=epoch;busy=true;error="";render();
  await new Promise((resolve)=>setTimeout(resolve,550));
  try{await mutate((fresh)=>{if(token!==epoch||session?.id!==payload.user)throw Error("The demo session changed. Select a seat again.");return book(fresh,payload);});selected=null;toast("Seat reserved locally. Enjoy your little break.");}
  catch(e){error=e.code?`${e.code}\n${e.message}`:e.message;if(e.code==="SEAT_UNAVAILABLE")selected=null;}
  finally{busy=false;render();}
}
function download(name,text){const link=document.createElement("a"),url=URL.createObjectURL(new Blob([text],{type:"application/json"}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function confirm(title,copy,fn){$("confirm-title").textContent=title;$("confirm-copy").textContent=copy;pendingAction=fn;$("confirm").showModal();}
document.addEventListener("click",async(event)=>{
  const button=event.target.closest("button");if(!button)return;
  if(button.dataset.close){$(button.dataset.close).close();return;}
  if(button.id==="open-login"){openLogin(location.hash==="#bookings"?"#bookings":null);return;}
  if(button.id==="logout"){epoch++;session=null;selected=null;try{localStorage.removeItem(SESSION);}catch{}error="";render();toast("Public demo signed out. Local booking history is retained.");}
  if(button.dataset.slot!==undefined){slot=Number(button.dataset.slot);selected=null;error="";render();}
  if(button.dataset.seat){selected=button.dataset.seat;error="";render();}
  if(button.id==="book")await createBooking();
  if(button.dataset.cancel){const id=button.dataset.cancel;confirm("Make room for someone else?","This cancels only your future local demo seat. It will become available again.",async()=>{await mutate((fresh)=>cancel(fresh,id,session?.id));toast("Local seat cancelled and released.");});}
  if(button.id==="confirm-action"){button.disabled=true;try{await pendingAction?.();$("confirm").close();render();}catch(e){toast(e.message);}finally{button.disabled=false;}}
  if(button.id==="save-capacity"){const capacity=Number($("capacity").value);try{if(!Number.isInteger(capacity)||capacity<1||capacity>30)throw Error("Capacity must be a whole number from 1 to 30.");await mutate((fresh)=>{fresh.capacity=capacity;fresh.revision++;});render();toast("Illustrative manager capacity changed locally.");}catch(e){announce(e.message);}}
  if(button.id==="hold-seat"){const seat=selected;try{if(!seat)throw Error("Select an available seat first.");await mutate((fresh)=>{if(!validSlot(day,slot))throw Error("This slot has started.");const rows=active(fresh,day,slot);if(rows.some((b)=>b.seat===seat))throw Error("Seat already occupied.");if(rows.length>=fresh.capacity)throw Error("The demo manager capacity is reached.");if(fresh.bookings.length>=1000)throw Error("Demo record limit reached.");fresh.bookings.push({id:crypto.randomUUID(),day,slot,seat,user:`competing-${crypto.randomUUID()}`,status:"BOOKED",createdAt:now().toISOString()});fresh.revision++;});render();toast("A fictional colleague took the selected seat.");}catch(e){announce(e.message);}}
  if(button.id==="export"){download("blu-reserve-local-ledger.json",JSON.stringify({notice:"FICTIONAL LOCAL DEMO — NOT A RESERVATION RECEIPT",...state},null,2));toast("Local fictional ledger downloaded.");}
  if(button.id==="reset")confirm("Reset this local demo?","Only Blu Reserve's two versioned localStorage keys are replaced. Export your fictional ledger first. Other websites and keys are unchanged.",async()=>{epoch++;if(ram){state=initial();session=null;}else await navigator.locks.request(KEY,()=>{const fresh=initial();localStorage.setItem(KEY,JSON.stringify(fresh));localStorage.removeItem(SESSION);state=fresh;session=null;});broken=false;notice=ram?"RAM-only mode. No persistence or cross-tab coordination.":"";selected=null;error="";location.hash="#floor";toast("Only this demo's local state was reset.");});
});
document.addEventListener("change",(event)=>{if(event.target.id==="day"){const value=event.target.value;if(!value||value<today()||value>plusDay(today(),7)){event.target.value=day;toast("Choose today or a date within seven days.");return;}day=value;if(!validSlot(day,slot)){const next=SLOTS.find((s)=>validSlot(day,s.id));if(next)slot=next.id;}selected=null;error="";render();}});
$("login-form").addEventListener("submit",async(event)=>{
  event.preventDefault();const button=$("login-submit"),data=new FormData(event.currentTarget),token=epoch;button.disabled=true;button.textContent="Opening local demo…";$("login-error").textContent="";
  await new Promise((resolve)=>setTimeout(resolve,350));
  try{const user=login(data.get("employee"),data.get("password"));if(token!==epoch)throw Error("The local demo was reset. Try again.");if(!ram)localStorage.setItem(SESSION,JSON.stringify(user));session=user;event.currentTarget?.reset();$("login-form").reset();$("login").close();if(pendingTarget?.startsWith("#"))location.hash=pendingTarget;render();toast("Welcome, Alex. This is a public local demo.");if(pendingTarget==="book")await createBooking();}catch(e){$("login-error").textContent=e.message;}finally{button.disabled=false;button.innerHTML=`Enter demo workspace ${icon("right")}`;}
});
window.addEventListener("storage",(event)=>{if(ram||![KEY,SESSION,null].includes(event.key))return;try{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):initial();session=readSession();broken=false;notice="";if(selected&&active(state,day,slot).some((b)=>b.seat===selected)&&!busy){selected=null;error="Availability changed in another tab. Choose a new seat.";}render();}catch(e){broken=true;notice=e.message;render();}});
window.addEventListener("hashchange",()=>{error="";render();if(location.hash==="#bookings"&&!session)openLogin("#bookings");});
setInterval(()=>{if($("login").open||$("confirm").open||busy)return;const current=$("office-clock");if(current)current.textContent=`${new Intl.DateTimeFormat("en-GB",{hour:"2-digit",minute:"2-digit",timeZone:"UTC"}).format(now())} UTC now`;document.querySelectorAll("[data-slot]").forEach((el)=>el.disabled=!validSlot(day,Number(el.dataset.slot)));if(selected&&!validSlot(day,slot)){selected=null;error="INVALID_TIME_RANGE\nThis slot has started. Choose a future slot.";render();}},30000);
render();
